internal class GUPBasePriceVersionCopy extends RunBase
{
    GUPBasePriceVersion     callerBasePriceVersion;
        
    GUPBasePriceVersionId   versionId;
    GUPBasePriceVersionName versionName;
    DialogField             versionIdDlgField;
    DialogField             versionNameDlgField;

    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
        callerBasePriceVersion,
        versionId,
        versionName
    #ENDMACRO

}

Method.Source:
public static GUPBasePriceVersionCopy construct()
{
    return new GUPBasePriceVersionCopy();
}

    public boolean unpack(container packedClass)
    {
        Integer     version         = RunBase::getVersion(packedClass);

        switch (version)
        {
            case #CurrentVersion :
                [version, #CurrentList] = packedClass;

                break;

            default :
                return false;
        }

        return true;
    }

    public Object dialog()
    {
        DialogRunbase dialog = super();

        dialog.addGroup("@GlobalUnifiedPricing:GUPBasePriceVersionTable");
        versionIdDlgField   = dialog.addFieldValue(extendedTypeStr(GUPBasePriceVersionId), versionId);
        versionNameDlgField = dialog.addFieldValue(extendedTypeStr(GUPBasePriceVersionName), versionName);

        return dialog;
    }

    public boolean getFromDialog()
    {
        boolean ret = super();

        versionId   = versionIdDlgField.value();
        versionName = versionNameDlgField.value();

        return ret;
    }

    public static void main(Args args)
    {
        GUPBasePriceVersion             basePriceVersion;
        GUPBasePriceVersionCopy         basePriceVersionCopy;
        Common                          record;

        using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
        {
            basePriceVersionCopy = GUPBasePriceVersionCopy::construct();
            if (basePriceVersionCopy.prompt())
            {
                if (basePriceVersionCopy.initFromArgs(args))
                {
                    basePriceVersionCopy.runOperation();
                }
                else
                {
                    throw error(Error::missingRecord(funcName()));
                }
            }
        }
    }

    public boolean initFromArgs(Args args)
    {
        boolean ret = true;

        if (args && args.record() && args.dataset() == tableNum(GUPBasePriceVersion))
        {
            callerBasePriceVersion = args.record();
        }
        else
        {
            ret = false;
        }

        return ret;
    }

    public void run()
    {
        #OCCRetryCount

        if (callerBasePriceVersion)
        {
            GUPBasePriceVersion newBasePriceVersion;
            newBasePriceVersion.initFromGUPBasePriceVersion(callerBasePriceVersion);
            newBasePriceVersion.VersionId   = versionId;
            newBasePriceVersion.Name        = versionName;

            try
            {
                if (newBasePriceVersion.validateWrite())
                {
                    ttsbegin;
                    newBasePriceVersion.insert();
                    ttscommit;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
        }
    }

    public boolean validate(Object calledFrom = null)
    {
        boolean ret;
    
        ret = super(calledFrom);

        if (versionId)
        {
            if (GUPBasePriceVersion::exist(versionId))
            {
                ret = checkFailed(strFmt("@SYS153389", tablePName(GUPBasePriceVersion), tableStr(GUPBasePriceVersion)));
            }
        }
        else
        {
            ret = checkFailed(strFmt("@SYS84378", extendedTypeId2pname(extendedTypeNum(GUPBasePriceVersionId))));
        }
    
        return ret;
    }
